from collections import deque, defaultdict
R=C=30
seen=set(); comps=[]; lab={}
for r in range(R):
 for c in range(C):
  if grid[r][c] and (r,c) not in seen:
   q=[(r,c)]; seen.add((r,c)); comp=[]
   while q:
    x,y=q.pop(); comp.append((x,y))
    for dx,dy in [(1,0),(-1,0),(0,1),(0,-1)]:
     z=(x+dx,y+dy)
     if 0<=z[0]<R and 0<=z[1]<C and grid[z[0]][z[1]] and z not in seen: seen.add(z);q.append(z)
   comps.append(comp)
for i,comp in enumerate(comps):
 for x in comp: lab[x]=i
print('components',len(comps))
for i,comp in enumerate(comps):
 marks=[(p,grid[p[0]][p[1]]) for p in comp if grid[p[0]][p[1]]>1]
 if marks: print(i,len(comp),marks)
# eligible 3x3 interior 1 cells, assigned component, summarize coords
inners=defaultdict(list)
for r in range(1,29):
 for c in range(1,29):
  if grid[r][c]==1 and all(grid[i][j]!=0 for i in range(r-1,r+2) for j in range(c-1,c+2)):
   inners[lab[r,c]].append((r,c))
print('interiors by component')
for i,pts in inners.items():
 print(i,len(pts), 'marker',[(p,grid[p[0]][p[1]]) for p in comps[i] if grid[p[0]][p[1]]>1],pts[:30])

markers={i:next((grid[r][c] for r,c in comp if grid[r][c]>1),None) for i,comp in enumerate(comps)}
out=[row[:] for row in grid]
changed=defaultdict(list)
for r in range(1,29):
 for c in range(1,29):
  if grid[r][c]==1 and all(grid[i][j]!=0 for i in range(r-1,r+2) for j in range(c-1,c+2)):
   color=markers[lab[r,c]]
   if color:
    out[r][c]=color; changed[color].append((r,c))
print({k:len(v) for k,v in changed.items()})
print('\n'.join(' '.join(map(str,row)) for row in out))
